#ifndef IMHOTEP_IO_SAVE_SCHEMA_H
#define IMHOTEP_IO_SAVE_SCHEMA_H

#include <stdint.h>

#define SAVE_SCHEMA_RECORDS 181 /* @bin 0x004D41E0 reads chunks 0..180 */
#define SAVE_VERSION 160        /* @bin 0x004D41E0 version global := 160 (0xA0) */

typedef struct {
    uint32_t compressed;
    uint32_t address;         /* the Pharaoh.exe variable the chunk is loaded into */
    uint32_t elem_size;
    uint32_t elem_count;
    uint32_t converter_below; /* a converter (game code) runs for file versions below this; 0 = none */
} save_schema_record;

extern const save_schema_record save_schema[SAVE_SCHEMA_RECORDS];

#endif
